import {SETTINGS,makeCase,verify,derive,graphEdges,canDiscover,accuse,breakCase,parseSeed} from './engine.js';
import {configureWorld,worldMode,introCamera} from './world.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],ui=$('#ui');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=[{seed:1042,setting:'manor'},{seed:2087,setting:'train'},{seed:3916,setting:'museum'}];
let library=[...defaults],saves={},current,certificate,progress,view='archive',place=0,selected=null,sound=false,audio,timeline=false,author=false,graphCase,highlight=[],generated=null,labResults=[],worker,inspectedNode=null;
try{const stored=JSON.parse(localStorage.getItem('cluemesh-v2')||'null');if(stored){library=stored.library.filter(x=>SETTINGS[x.setting]&&Number.isInteger(x.seed)&&x.seed>=0&&x.seed<=4294967295);saves=stored.saves||{}}}catch{}if(!library.length)library=[...defaults];
function persist(){try{localStorage.setItem('cluemesh-v2',JSON.stringify({library,saves}))}catch{toast('Browser storage is unavailable. Keep this tab open to retain progress.')}}
function loadCase(spec){const c=makeCase(spec.seed,spec.setting),r=verify(c);if(!r.ok){toast('This case has failed verification and cannot open.');return false}current=c;certificate=r;graphCase=c;progress=saves[c.id]??={found:[],links:[],positions:{},solved:false};progress.positions??={};selected=null;inspectedNode=null;place=0;configureWorld(c);$('#count').textContent=progress.found.length;$('#footer-case').textContent=`FILE ${c.seed} / ${SETTINGS[c.setting].name.toUpperCase()}`;return true}loadCase(library[0]);
function tone(f=350){if(!sound)return;audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.start();o.stop(audio.currentTime+.18)}
let tt;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(tt);tt=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function portrait(i=0){const skin=['#b98b66','#c5a385','#987653','#d1b493'][i%4],coat=['#465b61','#514b42','#66614b','#584c43'][i%4];return `<svg viewBox="0 0 140 150" role="img" aria-label="Illustrated fictional adult"><path fill="#6e7167" d="M0 0h140v150H0z"/><path fill="#909187" d="M0 0h80L0 120z"/><path fill="${coat}" d="M7 150l10-39 37-15h32l36 15 12 39z"/><path fill="#d4c5a7" d="M53 98l17 17 18-17-9 48H62z"/><path fill="#322b25" d="M67 116h7l7 34H61z"/><path fill="${skin}" d="M41 36l13-15h32l13 16-5 45-22 21-24-20z"/><path fill="#3d322a" d="M40 47l3-23 22-13 27 8 11 20-8 14-8-20-32 4-11 16z"/><path fill="#a7795b" d="M72 44l13 29-14 6z"/><path stroke="#40362c" stroke-width="3" d="M52 53h10m17 0h10M62 85h19"/><path fill="#7e5c45" d="M47 73l8 11 14 8-17-3z"/></svg>`}
function stamp(ok,text){return `<span class="stamp ${ok?'good':'bad'}">${text||(ok?'VERIFIED':'REJECTED')}</span>`}
function meta(c){const r=verify(c);return `<span>${c.people.length} SUSPECTS</span><span>${c.clues.length} CLUES</span><span>${r.validRoutes.length} PATHS</span>`}
function go(v){if(['scene','board','accuse'].includes(v)&&!verify(current).ok){toast('Rejected cases cannot be played.');return}view=v;selected=null;$('#detail').classList.add('hidden');$('#hotspots').innerHTML='';document.body.dataset.view=v;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));worldMode(v,place);render();ui.scrollTop=0;tone(230)}
$$('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='graph'){graphCase=current;highlight=[]}go(b.dataset.view)});
function render(){if(view==='archive')archive();if(view==='brief')brief();if(view==='scene')investigate();if(view==='board')board();if(view==='accuse')accusation();if(view==='graph')graph();if(view==='generator')generator();}
function archive(){ui.innerHTML=`<section class="archive-head"><div><span class="eyebrow">DEPARTMENT OF UNFINISHED BUSINESS</span><h1>Choose your next mystery.</h1><p>Pull a file from the drawer. Every released case has a verified path to the truth.</p></div><button id="new-case" class="primary">＋ Generate a mystery</button></section><section class="folder-shelf">${library.map((spec,i)=>{const c=makeCase(spec.seed,spec.setting),p=saves[c.id];return `<button class="folder" data-file="${i}" aria-label="Open ${esc(c.title)}, seed ${c.seed}"><span class="folder-tab">${['I','II','III','IV','V','VI'][i%6]} &nbsp; ${SETTINGS[c.setting].name}</span><span class="folder-top">CASE FILE / ${c.seed}<span>${p?.solved?'CLOSED':p?.found.length?'IN PROGRESS':'UNOPENED'}</span></span><span class="polaroid">${portrait(i%4)}<em>${c.victim}</em></span><span class="folder-title">${c.title}</span><span class="folder-classified">CONFIDENTIAL</span><span class="folder-details">VICTIM &nbsp; ${c.victim}<br>INCIDENT &nbsp; ${c.crimeTime}<br>SEED &nbsp; ${c.seed}</span><span class="folder-bottom">${stamp(true,p?.solved?'CASE CLOSED':'VERIFIED')}<span>${p?.found.length||0} / ${c.clues.length} CLUES</span></span><span class="hazard"></span></button>`}).join('')}</section><div class="archive-note"><span>✦ Choose a different seed to change the people, culprit, motive and evidence.</span><button id="resume" class="text-button">Resume file ${current.seed} →</button></div>`;$('#new-case').onclick=()=>go('generator');$('#resume').onclick=()=>go('scene');$$('[data-file]').forEach(b=>b.onclick=()=>{if(loadCase(library[+b.dataset.file])){go('brief');ui.classList.remove('folder-opening');void ui.offsetWidth;ui.classList.add('folder-opening')}})}
function brief(){ui.innerHTML=`<section class="case-document paper"><div class="document-top"><span>CASE FILE: ${current.seed}</span><span>ARCHIVE No.<br>${current.id}</span></div><div class="brief-heading"><div class="polaroid victim">${portrait(current.seed%4)}<em>${current.victim}</em></div><div><span class="eyebrow">SPECIAL INVESTIGATION FILE</span><h1>${current.title}</h1>${stamp(true)}<p>${SETTINGS[current.setting].name} / ${current.crimeTime}</p></div></div><div class="hazard"></div><dl><dt>SUBJECT</dt><dd>${current.victim}</dd><dt>LOCATION</dt><dd>${current.places[0]}</dd><dt>ASSIGNMENT</dt><dd>Establish motive, means and opportunity.</dd></dl><h3>RECOVERED INCIDENT REPORT</h3><p>${current.brief}</p><p class="typed-note">Some accounts may be false. Corroborate them with independent records. Evidence with a prerequisite opens when you recover the required clue.</p><div class="certificate-strip">${meta(current)}<span>SHORTEST PROOF: ${certificate.shortest} CLUES</span></div><div class="actions"><button class="primary" id="begin">${progress.found.length?'Continue investigation':'Begin investigation'} →</button><button class="text-button" id="files">← Choose another file</button></div></section>`;$('#begin').onclick=()=>go('scene');$('#files').onclick=()=>go('archive')}
function investigate(){ui.innerHTML=`<section class="scene-heading"><div><span class="eyebrow">FILE ${current.seed} / ${current.title}</span><h1>${current.places[place]}</h1><p>Search the room. Examine the records. Question the witnesses.</p></div><div class="location-tabs">${current.places.map((p,i)=>`<button class="chip ${i===place?'selected':''}" data-place="${i}">${i+1}. ${p}</button>`).join('')}</div></section><section class="witness-strip"><span class="eyebrow">PERSONS OF INTEREST / CLICK TO INTERVIEW</span><div>${current.people.map((p,i)=>`<button class="witness" data-person="${i}"><span>${portrait(i)}</span><b>${p.name}<small>${p.role}</small></b></button>`).join('')}</div><p>${progress.found.length} / ${current.clues.length} EVIDENCE RECOVERED <button id="to-board">Open evidence board →</button></p></section>`;$('#hotspots').innerHTML=current.clues.filter(c=>c.place===place&&c.interview===undefined).map(c=>`<button id="hot-${c.id}" class="hotspot ${progress.found.includes(c.id)?'found':''}" data-clue="${c.id}"><b>${progress.found.includes(c.id)?'✓':canDiscover(current,c.id,progress.found)?'+':'⌑'}</b>${c.name}</button>`).join('');$$('[data-place]').forEach(b=>b.onclick=()=>{place=+b.dataset.place;worldMode('scene',place);render();tone()});$$('[data-clue]').forEach(b=>b.onclick=()=>showClue(b.dataset.clue));$$('[data-person]').forEach(b=>b.onclick=()=>showClue(current.clues.find(c=>c.interview===+b.dataset.person).id));$('#to-board').onclick=()=>go('board')}
function showClue(id){const c=current.clues.find(c=>c.id===id),allowed=canDiscover(current,id,progress.found),missing=c.requires.filter(p=>!progress.found.includes(p));$('#detail').classList.remove('hidden');$('#detail').innerHTML=`<button class="close" aria-label="Close evidence">×</button><span class="eyebrow">EVIDENCE TAG: ${id.toUpperCase()}</span>${c.interview!==undefined?`<div class="polaroid witness-photo">${portrait(c.interview)}<em>${current.people[c.interview].name}</em></div>`:''}<h2>${c.name}</h2><div class="ruled"><b>${c.interview!==undefined?'RECOVERED STATEMENT':'EXAMINATION NOTES'}</b><p>${allowed?c.text:`This record is sealed until you recover: ${missing.map(id=>current.clues.find(c=>c.id===id)?.name||id).join(', ')}.`}</p></div><small>${c.trusted?'INDEPENDENT RECORD':'WITNESS ACCOUNT — CORROBORATION REQUIRED'}</small><button class="primary" id="collect" ${!allowed?'disabled':''}>${progress.found.includes(id)?'Evidence already filed':allowed?'Pin to evidence board':'Prerequisite not yet recovered'} →</button>`;$('#detail .close').onclick=()=>$('#detail').classList.add('hidden');$('#collect').onclick=()=>{if(!canDiscover(current,id,progress.found))return;if(!progress.found.includes(id)){progress.found.push(id);persist();$('#count').textContent=progress.found.length;tone(500);toast('Filed: '+c.name)}$('#detail').classList.add('hidden');render()}}
function board(){ui.innerHTML=`<section class="page-heading"><div><span class="eyebrow">FILE ${current.seed} / ${current.title}</span><h1>Follow the thread.</h1><p>${progress.found.length} clues recovered · ${progress.links.length} connections · Click two pins to connect. Drag cards to rearrange.</p></div><div class="actions"><button class="chip" id="timeline">${timeline?'Evidence board':'Reconstruct timeline'}</button><button class="primary" id="accuse">Make an accusation →</button></div></section><section class="corkboard">${timeline?timelineHTML():`<div class="evidence-grid" id="cards">${progress.found.map((id,i)=>{const c=current.clues.find(c=>c.id===id);return `<article class="evidence-card paper" data-card="${id}" style="--tilt:${(i%3-1)*2}deg;transform:translate(${progress.positions[id]?.x||0}px,${progress.positions[id]?.y||0}px) rotate(var(--tilt))"><button class="pin" data-pin="${id}" aria-label="Connect ${esc(c.name)}"></button><small>EXHIBIT ${String(i+1).padStart(2,'0')} / ${c.kind.toUpperCase()}</small><h3>${c.name}</h3><p>${c.text}</p><button class="read-clue" data-read="${id}">Read record ↗</button></article>`}).join('')}<svg class="board-svg" id="strings"></svg></div>`}${!progress.found.length?'<div class="empty"><h2>An empty board. A fresh mystery.</h2><p>Search the room and interview the four witnesses to pin your first record.</p><button class="primary" id="search">Start investigating →</button></div>':''}<div class="link-list">${progress.links.map((l,i)=>`<button data-unlink="${i}">${l.map(id=>current.clues.find(c=>c.id===id).name).join(' ↔ ')} ×</button>`).join('')}</div><p class="board-hint">Red string records your theory. The accusation verifier checks the attached evidence and its prerequisites.</p></section>`;$('#timeline').onclick=()=>{timeline=!timeline;render()};$('#accuse').onclick=()=>go('accuse');$('#search')?.addEventListener('click',()=>go('scene'));$$('[data-read]').forEach(b=>b.onclick=()=>showClue(b.dataset.read));$$('[data-unlink]').forEach(b=>b.onclick=()=>{progress.links.splice(+b.dataset.unlink,1);persist();render()});$$('[data-pin]').forEach(b=>b.onclick=()=>{const id=b.dataset.pin;if(!selected){selected=id;b.classList.add('selected');return}if(selected!==id&&!progress.links.some(l=>l.includes(id)&&l.includes(selected))){progress.links.push([selected,id]);const conflict=current.contradictions.some(x=>[selected,id].includes(x.a)&&[selected,id].includes(x.b));toast(conflict?'CONFLICT: the independent passage record disproves this witness account.':'Evidence connection pinned.');tone(conflict?140:450);persist()}selected=null;render()});
 $$('[data-card]').forEach(el=>{let start;el.onpointerdown=e=>{if(e.target.closest('button'))return;const pos=progress.positions[el.dataset.card]||{x:0,y:0};start={x:e.clientX,y:e.clientY,px:pos.x,py:pos.y};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!start)return;const x=Math.max(-100,Math.min(150,start.px+e.clientX-start.x)),y=Math.max(-60,Math.min(150,start.py+e.clientY-start.y));progress.positions[el.dataset.card]={x,y};el.style.transform=`translate(${x}px,${y}px) rotate(var(--tilt))`;drawLinks()};el.onpointerup=()=>{if(start){persist();start=null}};el.onpointercancel=()=>{start=null}});requestAnimationFrame(drawLinks)}
function drawLinks(){const svg=$('#strings'),root=$('#cards');if(!svg)return;const base=root.getBoundingClientRect();svg.innerHTML=progress.links.map(([a,b])=>{const ea=document.querySelector(`[data-pin="${a}"]`),eb=document.querySelector(`[data-pin="${b}"]`);if(!ea||!eb)return '';const A=ea.getBoundingClientRect(),B=eb.getBoundingClientRect();return `<line x1="${A.x+A.width/2-base.x}" y1="${A.y+A.height/2-base.y}" x2="${B.x+B.width/2-base.x}" y2="${B.y+B.height/2-base.y}"/>`}).join('')}addEventListener('resize',drawLinks);
function timelineHTML(){const entries=current.timeline.filter(e=>progress.found.includes(e.clue));return `<div class="timeline"><h2>Reconstruction of events</h2><div>${entries.map(e=>`<article class="paper"><i></i><strong>${e.time}</strong><p>${e.text}</p><small>Source: ${current.clues.find(c=>c.id===e.clue).name}</small></article>`).join('')||'<p class="empty">Recover the time-of-death report, key register and passage log to reconstruct the evening.</p>'}</div></div>`}
function accusation(){ui.innerHTML=`<section class="page-heading"><div><span class="eyebrow">FILE ${current.seed} / FINAL ACCOUNT</span><h1>A theory needs evidence.</h1><p>Select a suspect and attach a complete proof, including prerequisite records.</p></div><button class="chip" id="back">← Evidence board</button></section><section class="accusation paper"><div class="suspect-grid">${current.people.map((p,i)=>`<button class="suspect" data-suspect="${p.id}"><span class="polaroid">${portrait(i)}<em>${p.name}</em></span><small>${p.role}</small></button>`).join('')}</div><h3>ATTACHED EXHIBITS</h3><div class="attach-list">${progress.found.map(id=>`<label><input type="checkbox" value="${id}"> ${current.clues.find(c=>c.id===id).name}</label>`).join('')||'<p>Collect evidence before filing an accusation.</p>'}</div><div class="actions"><button class="primary" id="submit">Submit for verification →</button><button class="text-button" id="attach-all">Attach all recovered evidence</button></div><div id="verdict" role="status"></div></section>`;let suspect=null;$('#back').onclick=()=>go('board');$$('[data-suspect]').forEach(b=>b.onclick=()=>{suspect=b.dataset.suspect;$$('[data-suspect]').forEach(x=>x.classList.toggle('selected',x===b))});$('#attach-all').onclick=()=>$$('.attach-list input').forEach(x=>x.checked=true);$('#submit').onclick=()=>{if(!suspect){toast('Select a suspect before filing.');return}const r=accuse(current,suspect,$$('.attach-list input:checked').map(x=>x.value));$('#verdict').innerHTML=`<div class="verdict">${stamp(r.ok,r.ok?'CASE CLOSED':'NOT PROVEN')}<p>${r.text}</p>${r.ok?`<p>Verified route: ${r.route.map(id=>current.clues.find(c=>c.id===id).name).join(' → ')}</p><button class="primary" id="next">Choose another mystery →</button>`:''}</div>`;if(r.ok){progress.solved=true;persist();$('#next').onclick=()=>go('archive')}tone(r.ok?650:140)}}
function reportHTML(r){return `<div class="verification-report">${stamp(r.ok)}<div class="check-grid">${r.checks.map(x=>`<span class="${x.ok?'pass':'fail'}">${x.ok?'✓':'×'} ${x.name}</span>`).join('')}</div>${r.ok?`<p>${r.validRoutes.length} minimal evidence paths · shortest proof ${r.shortest} clues · ${r.reachable.length}/${r.total} graph nodes reachable.<br>Other suspects’ conclusions remain unproven by design.</p>`:`<ul>${r.errors.map(e=>`<li><b>${esc(e.node)}</b>: ${esc(e.message)}<small>Repair: ${esc(e.fix)}</small></li>`).join('')}</ul><p class="blocked">PLAY BLOCKED — repair and verify before release.</p>`}</div>`}
function graph(){const c=graphCase||current,r=verify(c),proofs=derive(c,author?null:(c.id===current.id?progress.found:[]));ui.innerHTML=`<section class="page-heading"><div><span class="eyebrow">DIRECTED EVIDENCE GRAPH / SEED ${c.seed}</span><h1>The logic behind the mystery.</h1><p>Entry points → discoverable clues → facts & events → justified conclusions.</p></div><button class="chip" id="graph-back">← Case files</button></section><section class="graph-workspace paper"><div class="graph-controls"><label><input id="author" type="checkbox" ${author?'checked':''}> Author view — reveal solution</label><button class="chip" id="shortest">Highlight shortest proof</button><label>Fault test <select id="fault"><option value="none">Original case</option><option value="missing">Missing prerequisite</option><option value="contradiction">Trusted-record contradiction</option><option value="unreachable">Unreachable conclusion</option><option value="cycle">Circular dependency</option></select></label><button class="chip" id="verify-again">Run verifier</button></div><div class="graph-legend"><span>→ requires / reveals / supports</span><span class="red">⇢ contradicts / refutes</span><span class="green">● discovered or proven</span><span>○ not yet proven</span></div><div class="graph-scroll"><svg id="graph-svg" viewBox="0 0 1240 1300" role="group" aria-label="Directed graph of suspects, locations, clues, facts, events and conclusions"></svg></div><div id="node-detail" class="node-detail">Select a node to inspect its prerequisites and inference rules.</div><div id="graph-report">${reportHTML(r)}</div></section>`;$('#graph-back').onclick=()=>go('archive');$('#author').onchange=e=>{author=e.target.checked;highlight=[];graph()};$('#shortest').onclick=()=>{if(!author){toast('Enable Author view first: a shortest proof reveals the solution.');return}highlight=r.validRoutes[0]||[];paintGraph(c,r,proofs);toast(highlight.length?'Shortest proof highlighted.':'No proof exists for this rejected case.')};$('#fault').value=c.fault||'none';$('#fault').onchange=e=>{graphCase=e.target.value==='none'?makeCase(c.seed,c.setting):breakCase(makeCase(c.seed,c.setting),e.target.value);graphCase.fault=e.target.value;highlight=[];graph()};$('#verify-again').onclick=()=>{$('#graph-report').innerHTML=reportHTML(verify(c));$('#graph-report').classList.remove('scan');void $('#graph-report').offsetWidth;$('#graph-report').classList.add('scan');tone(r.ok?550:150)};paintGraph(c,r,proofs)}
function paintGraph(c,r,proofs){const cols=[c.nodes.filter(n=>n.source),c.nodes.filter(n=>n.type==='clue'),c.nodes.filter(n=>n.type==='fact'||n.type==='event'),c.nodes.filter(n=>n.type==='conclusion')],pos=new Map();cols.forEach((ns,col)=>ns.forEach((n,i)=>pos.set(n.id,{x:25+col*310,y:65+i*75})));const hidden=n=>!author&&!n.source&&!proofs.get(n.id)?.length;const lit=new Set(highlight);if(highlight.length){const p=derive(c,highlight);for(const [id,paths]of p)if(paths.length)lit.add(id)}const svg=$('#graph-svg');svg.innerHTML=`<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#74664d"/></marker><marker id="redarrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z" fill="#a43e31"/></marker></defs>${['ENTRY POINTS','CLUES / PREREQUISITES','FACTS & EVENTS','CONCLUSIONS'].map((s,i)=>`<text x="${25+i*310}" y="25" class="column-title">${s}</text>`).join('')}${graphEdges(c).map(e=>{const a=pos.get(e.from),b=pos.get(e.to);if(!a||!b)return '';const red=['contradicts','refutes'].includes(e.type),on=lit.has(e.from)&&lit.has(e.to);const x1=a.x+245,x2=b.x,y1=a.y+26,y2=b.y+26;return `<path d="M${x1} ${y1} C${x1+35} ${y1},${x2-40} ${y2},${x2} ${y2}" class="graph-edge ${red?'conflict':''} ${on?'lit':''}" marker-end="url(#${red?'redarrow':'arrow'})"><title>${e.from} ${e.type} ${e.to}</title></path>`}).join('')}${c.nodes.map(n=>{const p=pos.get(n.id),known=!hidden(n),text=known?n.name:n.type==='clue'?'Unrecovered evidence':n.type==='conclusion'?'Unproven suspect conclusion':'Unproven inference',bad=r.errors.some(e=>e.node===n.id);return `<g class="graph-node ${proofs.get(n.id)?.length?'reached':''} ${bad?'invalid':''} ${lit.has(n.id)?'lit':''}" transform="translate(${p.x} ${p.y})" data-node="${n.id}" role="button" tabindex="0" aria-label="${esc(text)}"><rect width="245" height="54" rx="3"/><text x="12" y="19" class="node-type">${n.type.toUpperCase()}</text><text x="12" y="39">${esc(text.length>30?text.slice(0,29)+'…':text)}</text></g>`}).join('')}`;$$('[data-node]').forEach(el=>{const show=()=>{const n=c.nodes.find(x=>x.id===el.dataset.node),names=ids=>ids.map(id=>{const p=c.nodes.find(n=>n.id===id);return !p?id:hidden(p)?`[unrecovered ${p.type}]`:p.name}).join(' + ');$('#node-detail').innerHTML=`<b>${hidden(n)?'Unrecovered node':esc(n.name)}</b><p>Type: ${n.type}. ${n.source?'Entry point.':n.type==='clue'?'Discover after: '+esc(names(n.requires)):n.alternatives.length?'Derive when: '+n.alternatives.map(a=>`(${esc(names(a))})`).join(' OR '):'No supporting rule for this hypothesis.'}</p>${author&&n.text?`<p>${esc(n.text)}</p>`:''}`};el.onclick=show;el.onkeydown=e=>{if(e.key==='Enter')show()}})}
function generator(){ui.innerHTML=`<section class="page-heading"><div><span class="eyebrow">CASE ASSEMBLY / AUTHORING DESK</span><h1>A new mystery. A checkable truth.</h1><p>Choose a setting and seed. Generate → verify → release to the archive.</p></div><button class="chip" id="gen-back">← Case files</button></section><section class="generator-layout"><form id="generate-form" class="paper generator-form"><h2>Open a new investigation</h2><label>SETTING<select id="setting" aria-label="Setting">${Object.entries(SETTINGS).map(([id,s])=>`<option value="${id}">${s.name}</option>`).join('')}</select></label><label>CASE SEED<input id="seed" aria-label="Case seed" inputmode="numeric" value="${generated?.seed??5271}" required pattern="[0-9]{1,10}" aria-describedby="seed-help"></label><small id="seed-help">Same seed + setting = the same mystery. Range: 0–4294967295.</small><button type="button" id="random" class="text-button">↻ Choose a random seed</button><label>AUTHORING FAULT TEST<select id="gen-fault" aria-label="Authoring fault test"><option value="none">None — build a playable mystery</option><option value="missing">Remove a required lab report</option><option value="contradiction">Contradict the trusted timeline</option><option value="unreachable">Disconnect the conclusion</option><option value="cycle">Create a circular prerequisite</option></select></label><button class="primary" type="submit">Generate & verify →</button><p class="form-note">Rules assemble the culprit, motive, testimony, alibis and clue dependencies from a shared timeline. No case opens without passing verification.</p></form><div class="paper generated-result" id="generated-result">${generated?generatedHTML(generated):'<span class="large-seal">CM</span><h2>Awaiting a new case file.</h2><p>Your verification certificate will appear here.<br>Every accepted mystery can be opened and played.</p>'}</div></section><section class="batch paper"><div><h2>Stress-test the authoring engine</h2><p>Generate 100 cases from the selected seed and setting. Inspect and play any verified result.</p></div><div class="actions"><button class="chip" id="batch-good">Test 100 constrained cases</button><button class="chip" id="batch-bad">Test fault-injected cases</button></div><div id="batch-result"></div></section>`;$('#gen-back').onclick=()=>go('archive');$('#setting').value=generated?.setting||current.setting;$('#random').onclick=()=>{$('#seed').value=crypto.getRandomValues(new Uint32Array(1))[0]};$('#generate-form').onsubmit=e=>{e.preventDefault();try{const seed=parseSeed($('#seed').value),setting=$('#setting').value,fault=$('#gen-fault').value;generated=fault==='none'?makeCase(seed,setting):breakCase(makeCase(seed,setting),fault);generated.fault=fault;$('#generated-result').innerHTML=generatedHTML(generated);bindGenerated();tone(verify(generated).ok?550:150)}catch(err){toast(err.message)}};$('#batch-good').onclick=()=>batch(false);$('#batch-bad').onclick=()=>batch(true);bindGenerated();if(labResults.length)showBatch()}
function generatedHTML(c){const r=verify(c);return `<span class="eyebrow">FILE ${c.seed} / ${SETTINGS[c.setting].name}</span><h2>${c.title}</h2><p>${c.brief}</p>${reportHTML(r)}<div class="actions"><button class="primary" id="play-generated" ${r.ok?'':'disabled'}>${r.ok?'File in archive & play →':'Rejected — cannot open'}</button><button class="text-button" id="inspect-generated">Inspect graph →</button></div>`}
function bindGenerated(){$('#play-generated')?.addEventListener('click',()=>{if(!generated||!verify(generated).ok){toast('Rejected cases cannot enter the archive.');return}const spec={seed:generated.seed,setting:generated.setting};if(!library.some(x=>x.seed===spec.seed&&x.setting===spec.setting))library.push(spec);persist();if(loadCase(spec))go('brief')});$('#inspect-generated')?.addEventListener('click',()=>{graphCase=generated;highlight=[];go('graph')})}
function batch(naive){let seed;try{seed=parseSeed($('#seed').value);if(seed>4294967196)throw new Error('Use a seed up to 4294967196 for a batch of 100.')}catch(e){toast(e.message);return}$('#batch-result').innerHTML='<p>Checking 100 evidence graphs…</p>';$('#batch-good').disabled=$('#batch-bad').disabled=true;worker??=new Worker('worker.js',{type:'module'});worker.onmessage=e=>{labResults=e.data;if(view==='generator'){showBatch();$('#batch-good').disabled=$('#batch-bad').disabled=false}};worker.onerror=()=>{if(view==='generator'){$('#batch-result').textContent='The worker could not start. Reload and retry.';$('#batch-good').disabled=$('#batch-bad').disabled=false}};worker.postMessage({seed,setting:$('#setting').value,naive})}
function showBatch(){const valid=labResults.filter(x=>x.result.ok).length;$('#batch-result').innerHTML=`<div class="batch-metrics"><b>${valid}<small>VERIFIED & PLAYABLE</small></b><b>${100-valid}<small>REJECTED BEFORE RELEASE</small></b></div><div class="lab-grid">${labResults.map((x,i)=>`<button data-batch="${i}" class="seed ${x.result.ok?'':'bad'}" aria-label="Seed ${x.seed}, ${x.result.ok?'verified':'rejected'}">${x.seed}</button>`).join('')}</div><div id="batch-detail"></div>`;$$('[data-batch]').forEach(b=>b.onclick=()=>{const x=labResults[+b.dataset.batch];$('#batch-detail').innerHTML=`<h3>SEED ${x.seed}</h3>${reportHTML(x.result)}${x.result.ok?'<button class="primary" id="batch-play">Open this mystery →</button>':''}`;$('#batch-play')?.addEventListener('click',()=>{const spec={seed:x.seed,setting:x.setting};if(!library.some(s=>s.seed===x.seed&&s.setting===x.setting))library.push(spec);persist();if(loadCase(spec))go('brief')})})}
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';$('#introvideo').muted=!sound;tone()};
const video=$('#introvideo');let transitioning=false;function endIntro(){if(transitioning)return;transitioning=true;video.pause();introCamera();go('archive');$('#intro').classList.add('finishing');ui.classList.add('archive-arrival');setTimeout(()=>{$('#intro').classList.add('hidden');$('#intro').classList.remove('finishing','playing');ui.classList.remove('archive-arrival');transitioning=false},1400)}
$('#enter').onclick=()=>{$('#intro').classList.add('playing');video.muted=!sound;video.play().catch(()=>{toast('Opening the archive.');endIntro()})};$('#skip').onclick=endIntro;video.onended=endIntro;video.onerror=()=>{if($('#intro').classList.contains('playing'))endIntro()};$('#replay').onclick=()=>{if(transitioning)return;$('#intro').classList.remove('hidden');$('#intro').classList.add('playing');video.currentTime=0;video.play().catch(endIntro)};addEventListener('keydown',e=>{if(e.key==='Escape'){$('#detail').classList.add('hidden');if(!$('#intro').classList.contains('hidden'))endIntro()}});go('archive');
